import {FHS_PLAQUETTE_REFERENCE} from './fhs-plaquette-reference.js?v=20261117-phonopy1';

export const FHS_PLAQUETTE_BRIDGE_HOOKS=Object.freeze({'geometry-topology':Object.freeze(['oriented-plaquette'])});
const owners=new WeakMap(),clone=value=>JSON.parse(JSON.stringify(value));let svgSerial=0;
const esc=value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const fmt=value=>value===null||value===undefined?'—':Math.abs(value)<5e-14?'0':Number(value.toPrecision(7)).toString();
const parametersText=result=>'QWZ · m='+fmt(result.parameters.mass)+' · N='+fmt(result.parameters.mesh)+' · s='+fmt(result.parameters.gaugeStrength);
const mul=(a,b)=>[a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]],conj=z=>[z[0],-z[1]],abs=z=>Math.hypot(z[0],z[1]),distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
const zfmt=z=>z===null?'—':Math.abs(z[1])<5e-14?fmt(z[0]):Math.abs(z[0])<5e-14?fmt(z[1])+'i':fmt(z[0])+(z[1]<0?' − ':' + ')+fmt(Math.abs(z[1]))+'i';
const finite=value=>typeof value==='number'&&Number.isFinite(value),pair=z=>Array.isArray(z)&&z.length===2&&z.every(finite);
const formula=value=>`<div class="fpb-formula" tabindex="0">${mathHTML(value,true)}</div>`;
const table=(caption,headers,rows)=>`<div class="fpb-table-wrap" tabindex="0"><table><caption>${esc(caption)}</caption><thead><tr>${headers.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map((x,i)=>(i?'<td data-math-ignore>':'<th scope="row" data-math-ignore>')+esc(x)+(i?'</td>':'</th>')).join('')+'</tr>').join('')}</tbody></table></div>`;
const select=(id,label,rows,value)=>`<label for="${id}">${esc(label)}<select id="${id}">${rows.map(([v,text])=>`<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const button=(id,label,disabled=false)=>`<button type="button" id="${id}"${disabled?' disabled':''}>${label}</button>`;
const references=()=>FHS_PLAQUETTE_REFERENCE.cases;
const reference=id=>references().find(row=>row.id===id)||references().find(row=>row.input.mass===-1)||references()[0];
const sourceKey=result=>'fhs-result:'+JSON.stringify(result?.parameters||{});
const readOpen=node=>typeof node?.open==='boolean'?node.open:node?.getAttribute?.('open')!==null;

/** Inspect four production overlaps only; no Hamiltonian/eigenvector solver. */
export function fhsPlaquetteLedger(result,{cellId='interior',frame='before'}={}){
 const replay=result?.fhsReplay;
 if(result?.model!=='qwz'||!replay)return null;
 if(replay.schemaVersion!==1||replay.convergenceIndex!==0||!Number.isInteger(replay.mesh)||replay.mesh<9||replay.mesh!==result.parameters?.mesh||replay.sewing!=='identity'||replay.orientation!=='kx then ky'||replay.complexEncoding!=='[real,imag]'||replay.linkThreshold!==1e-10||typeof replay.bandIsolated!=='boolean'||typeof replay.beforeLinksValid!=='boolean'||typeof replay.afterLinksValid!=='boolean'||!['before','after'].includes(frame))throw Error('Invalid FHS replay metadata.');
 const cell=replay.cells?.find(row=>row.id===cellId);
 if(!cell||!Array.isArray(cell.anchor)||cell.anchor.length!==2||!cell.anchor.every(x=>Number.isInteger(x)&&x>=0&&x<replay.mesh)||cell.corners?.length!==4||cell.gaugePhases?.length!==4||!cell.gaugePhases.every(finite))throw Error('Invalid FHS replay cell.');
 for(const corner of cell.corners)if(!Array.isArray(corner.index)||corner.index.length!==2||!corner.index.every(x=>Number.isInteger(x)&&x>=0&&x<replay.mesh)||!pair(corner.k)||!pair(corner.unwrappedK))throw Error('Invalid FHS replay corner.');
 const stages={};
 for(const name of ['before','after']){
  const raw=cell[name]?.rawForwardOverlaps;if(!Array.isArray(raw)||raw.length!==4||!raw.every(pair))throw Error('Invalid FHS replay overlaps.');
  const magnitudes=raw.map(abs),valid=replay.bandIsolated&&replay[name+'LinksValid']&&magnitudes.every(value=>value>replay.linkThreshold);
  const units=raw.map((value,i)=>magnitudes[i]>replay.linkThreshold?value.map(x=>x/magnitudes[i]):null),factors=units.map((value,i)=>value===null?null:i<2?value:conj(value));
  const products=[];let product=[1,0];if(valid)for(const value of factors){product=mul(product,value);products.push(product);}
  const loop=valid?product:null,flux=valid?-Math.atan2(loop[1],loop[0]):null,issuedLoop=cell[name].loop,issuedFlux=cell[name].fluxRad;
  if(valid){if(!pair(issuedLoop)||!finite(issuedFlux)||distance(loop,issuedLoop)>2e-14||Math.abs(flux-issuedFlux)>2e-14)throw Error('FHS replay product differs from production.');}
  else if(issuedLoop!==null||issuedFlux!==null)throw Error('Invalid FHS replay must retain null loop and flux.');
  stages[name]={raw:clone(raw),magnitudes,units,factors,products,loop,flux,valid,edgePhases:valid?factors.map(z=>Math.atan2(z[1],z[0])):null};
 }
 const endpoints=[[0,1],[1,2],[2,3],[3,0]],phaseDifferences=endpoints.map(([a,b])=>cell.gaugePhases[b]-cell.gaugePhases[a]);
 const covariance=stages.before.factors.map((value,i)=>value&&stages.after.factors[i]?distance(mul(value,[Math.cos(phaseDifferences[i]),Math.sin(phaseDifferences[i])]),stages.after.factors[i]):null);
 const valid=stages.before.valid&&stages.after.valid;
 if(valid&&covariance.some(value=>value===null||value>2e-13))throw Error('FHS replay endpoint phases differ from production.');
 return{mesh:replay.mesh,convergenceIndex:0,cell:clone(cell),frame,stages,current:stages[frame],phaseDifferences,covariance,
  endpointPhaseSum:phaseDifferences.reduce((a,b)=>a+b,0),loopDifference:valid?distance(stages.before.loop,stages.after.loop):null,
  principalEdgePhaseSum:stages[frame].edgePhases?.reduce((a,b)=>a+b,0)??null,
  branchInteger:valid?Math.round((stages[frame].edgePhases.reduce((a,b)=>a+b,0)+stages[frame].flux)/(2*Math.PI)):null};
}

/** Complete, supported input from a real reference or this result's parameters. */
export function fhsPlaquetteLabRequest(values={}){
 const input=values.result?.parameters||reference(values.caseId).input,keys=['model','mass','energyScale','t1','t2','mesh','pathSamples','gaugeStrength','kx','ky'];
 if(input?.model!=='qwz'||keys.some(key=>!Object.hasOwn(input,key)))throw Error('A complete QWZ input is required.');
 return{action:'quantum_geometry_lab',module:'geometry',input:Object.fromEntries(keys.map(key=>[key,clone(input[key])]))};
}
const questions=[
 {prompt:"Which factor describes the −x step from C to D?",answer:'conjugate',options:[['conjugate',"The complex conjugate of Ux(D)"],['forward',"Use Ux(D) directly"],['start',"Use Ux(C)"]],feedback:{conjugate:"Correct. The array stores the forward D→C link. The reverse C→D step requires its complex conjugate.",forward:"Ux(D) describes D→C. Reversing the step reverses its phase, so conjugation is required.",start:"Ux(C) points to another vertex to the right of C, rather than following this loop from C to D."}},
 {prompt:"The sum of four principal edge phases can contain an extra 2π. How should the plaquette flux be obtained?",answer:'product',options:[['product',"Multiply the four complex factors first, then take −Arg"],['sum',"Negate the direct sum of the four displayed phases"],['plus',"Take +Arg of the loop product"]],feedback:{product:"Correct. Individual principal edge phases can cross branches. Multiply first to take one consistent principal argument, then apply this site's minus sign.",sum:"Each displayed edge phase has its own principal branch. Their sum can differ by an integer multiple of 2π; return to the complex product.",plus:"This site uses A=i⟨u|∂u⟩ and the kx→ky orientation. Its production implementation takes −Arg."}},
 {prompt:"Does nonzero flux in one plaquette determine the Chern number of the entire band?",answer:'whole',options:[['whole',"No; sum over the full BZ and check the gap and grid"],['cell',"Yes; this flux is the Chern number"],['two',"Adding the two saved plaquettes is sufficient"]],feedback:{whole:"Correct. Only two plaquettes are saved for replay. The full base-grid sum comes from convergence[0]; the main result also requires the fine-grid and global-gap checks.",cell:"A plaquette flux is measured in radians. The Chern number is the full-BZ flux sum divided by 2π.",two:"Two examples cannot replace all N² plaquettes. The m=3 case also shows nonzero local contributions with a zero total."}},
 {prompt:"Which sewing is used when crossing +π to the stored −π vertex in this model?",answer:'identity',options:[['identity',"The identity matrix in the fixed periodic orbital basis"],['minus',"Add an extra spin-related minus sign"],['omit',"Omit the boundary link"]],feedback:{identity:"Correct. The two components use a fixed orbital basis with identity sewing at the periodic boundary. Arbitrary eigenvector phases still cancel around the loop.",minus:"This model does not introduce a spin 2π rotation or an extra minus sign. Its orbital sewing is explicitly the identity matrix.",omit:"Omitting boundary links cuts open the Brillouin torus and cannot reproduce the complete FHS sum."}}
];
const initial=()=>({open:false,proofOpen:false,caseId:reference().id,cellId:'interior',frame:'before',step:0,choices:['','','',''],checked:[false,false,false,false],note:'',copyOutcome:''});
function restore(saved){const state=initial();if(!saved||typeof saved!=='object')return state;for(const field of ['open','proofOpen'])state[field]=saved[field]===true;if(references().some(row=>row.id===saved.caseId))state.caseId=saved.caseId;if(['interior','boundary-xy'].includes(saved.cellId))state.cellId=saved.cellId;if(['before','after'].includes(saved.frame))state.frame=saved.frame;if(Number.isInteger(saved.step))state.step=Math.max(0,Math.min(8,saved.step));if(typeof saved.note==='string')state.note=saved.note.slice(0,2000);for(let i=0;i<4;i++)if(questions[i].options.some(([id])=>id===saved.choices?.[i])){state.choices[i]=saved.choices[i];state.checked[i]=saved.checked?.[i]===true;}return state;}
const getResult=(state,result)=>result||reference(state.caseId).result;
function loopSVG(step){const active=Math.max(0,Math.min(4,step-2)),arrow='fpb-arrow-'+(++svgSerial);return `<svg class="fpb-loop" viewBox="0 0 300 220" role="img" aria-label="Oriented plaquette from A to B to C to D"><defs><marker id="${arrow}" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="currentColor"></path></marker></defs>${['M70 170 L230 170','M250 150 L250 70','M230 50 L70 50','M50 70 L50 150'].map((d,i)=>`<path d="${d}"${i<active?' class="fpb-active"':''} marker-end="url(#${arrow})"></path>`).join('')}${[[50,170,'A'],[250,170,'B'],[250,50,'C'],[50,50,'D']].map(([x,y,t])=>`<circle cx="${x}" cy="${y}" r="17"></circle><text class="fpb-label" x="${x}" y="${y+6}" text-anchor="middle">${t}</text>`).join('')}<text x="143" y="204">+x</text><text x="264" y="116">+y</text><text x="139" y="27">−x</text><text x="12" y="116">−y</text></svg>`;}
function coordinatesHTML(ledger){const c=ledger.cell;return loopSVG(0)+table("Four actual vertices: array indices are [ky,kx], momenta are (kx,ky)",["Vertex","Index","Stored k","Unwrapped k along the loop",'α / rad'],c.corners.map((v,i)=>[['A','B','C','D'][i],v.index.join(', '),v.k.map(fmt).join(', '),v.unwrappedK.map(fmt).join(', '),fmt(c.gaugePhases[i])]))+"<p>At a boundary plaquette, the stored −π represents +π reached in the positive direction. These are neighboring points on the torus. The fixed periodic orbital basis uses identity sewing with no extra minus sign.</p>";}
function ledgerHTML(state,result){
 const r=fhsPlaquetteLedger(result,state),s=r.current,steps=Math.max(0,Math.min(4,state.step-2));
 let html=loopSVG(state.step)+table("Store forward overlaps, normalize, then reverse the last two links along the loop",["Forward array entry","Raw complex overlap","Magnitude","Unit link","Loop factor","Directed edge principal phase / rad"],['rx(A)：A→B','ry(B)：B→C','rx(D)：D→C','ry(A)：A→D'].map((label,i)=>[label,zfmt(s.raw[i]),fmt(s.magnitudes[i]),state.step>=1?zfmt(s.units[i]):'—',state.step>=2?zfmt(s.factors[i]):'—',state.step>=2?fmt(s.edgePhases?.[i]):'—']));
 if(!s.valid)return html+"<p class=\"fpb-warning\">The band gap is closed or a link overlap is invalid. Raw overlaps are finite-grid diagnostics only. Production loop and flux values are undefined and are not filled in as a Chern result.</p>";
 if(state.step>=1)html+=formula('U_\\mu=\\frac{r_\\mu}{|r_\\mu|}');
 if(state.step>=2)html+=formula('L=U_x(A)U_y(B)U_x(D)^*U_y(A)^*')+"<p>Conjugate the third and fourth entries to reverse D→C and A→D into C→D and D→A.</p>";
 if(steps)html+=table("Multiply one factor at a time along A→B→C→D→A",["Number of edges multiplied","Cumulative complex product"],s.products.slice(0,steps).map((value,i)=>[i+1,zfmt(value)]));
 if(state.step>=7)html+=table("Principal phases of the four directed edges",["Path","Phase / rad"],['A→B','B→C','C→D','D→A'].map((path,i)=>[path,fmt(s.edgePhases[i])]))+formula('\\phi=-\\operatorname{Arg}(L)')+table("Principal branch: multiply complex numbers, then take Arg once",["Comparison quantity","Value","Unit"],[["Direct sum of the four displayed edge phases",fmt(r.principalEdgePhaseSum),'rad'],['Arg(L)',fmt(-s.flux),'rad'],["Plaquette flux used here: −Arg(L)",fmt(s.flux),'rad'],["Integer multiple of 2π between the phase sum and Arg(L)",r.branchInteger,'1']])+"<p>The integer multiple of 2π comes from the separate principal branches of the edge phases. Their displayed sum is not the final plaquette flux.</p>";
 return html;
}
function gaugeHTML(state,result){const r=fhsPlaquetteLedger(result,state);if(state.step<8)return "<p>After replaying the four edges and minus Arg, reveal the final step to check gauge-endpoint cancellation in the same calculation.</p>";return table("Before and after the same gauge change: compare endpoint phases on each directed edge",["Path","αend−αstart","Original factor","Phase-transformed factor","Endpoint transformation residual"],['A→B','B→C','C→D','D→A'].map((name,i)=>[name,fmt(r.phaseDifferences[i]),zfmt(r.stages.before.factors[i]),zfmt(r.stages.after.factors[i]),fmt(r.covariance[i])]))+formula('(\\alpha_B-\\alpha_A)+(\\alpha_C-\\alpha_B)+(\\alpha_D-\\alpha_C)+(\\alpha_A-\\alpha_D)=0')+table("The closed loop is unchanged; individual displayed phases may cross branches",["Quantity","Value"],[["Sum of the four endpoint differences",fmt(r.endpointPhaseSum)],["Loop before gauge change",zfmt(r.stages.before.loop)],["Loop after gauge change",zfmt(r.stages.after.loop)],["Complex distance between the two loops",fmt(r.loopDifference)]])+"<p>These are the saved before/after data. Only the U(1) phase of the same band eigenvectors changes; the orbital basis and sewing stay fixed.</p>";}
function totalHTML(result,ledger){const rows=result.convergence||[];return table("Keep this plaquette, the base grid, and the main result distinct",["Object","Value","Scope"],[["This plaquette flux φ / rad",fmt(ledger.current.flux),"One plaquette"],["Base-grid FHS sum C_N",fmt(rows[0]?.value),'N='+ledger.mesh+'，convergence[0]'],["Fine-grid FHS sum",fmt(rows[1]?.value),'N='+String(rows[1]?.mesh??'—')+'，convergence[1]'],["Current main Chern result",fmt(result.topology?.value),"Reported after analytic-gap and two-grid checks"]])+formula('C_N=\\frac{1}{2\\pi}\\sum_{j,i}\\phi_{ji}')+"<p data-math-ignore>This card replays two actual plaquettes, without estimating the N²-plaquette sum from them. The complete base-grid value is the existing convergence[0] result. The main result uses the fine grid; an N-grid plaquette is not a fine-grid contribution. For m=3, local flux can be nonzero while the total Chern number is zero.</p>";}
function questionHTML(prefix,state,i){return `<section class="fpb-question"><h4>${questions[i].prompt}</h4>${select(prefix+'-q'+i,"Record a prediction first",[['',"Choose an answer"],...questions[i].options],state.choices[i])}${button(prefix+'-check'+i,"Check and explain",!state.choices[i])}<p id="${prefix}-feedback${i}" class="fpb-feedback" role="status"></p></section>`;}
function bodyHTML(prefix,state,result,mode,canCopy){const actual=getResult(state,result),ledger=fhsPlaquetteLedger(actual,state);return "<p class=\"fpb-scope\">Lower band, kx→ky orientation, and a fixed periodic orbital basis. This card reads actual FHS edge overlaps. Finite complex arithmetic explains the computed data without solving the Hamiltonian again.</p>"+'<p id="'+prefix+'-parameters" data-math-ignore>'+esc(parametersText(actual))+'</p>'+`<div class="fpb-controls">${mode==='lesson'?select(prefix+'-case',"Production Python reference",references().map(row=>[row.id,'QWZ · m='+row.input.mass+', N='+row.input.mesh+', s='+row.input.gaugeStrength]),state.caseId):''}${select(prefix+'-cell',"Choose a plaquette saved in this calculation",[['interior',"Interior plaquette"],['boundary-xy',"Across both x and y periodic boundaries"]],state.cellId)}${select(prefix+'-frame',"Choose the actual link set to display",[['before',"Original eigenvectors"],['after',"After the k-dependent gauge phase change"]],state.frame)}</div>`+`<section class="fpb-stage"><h3>1 · Vertices, orientation, and periodic boundaries</h3><div id="${prefix}-coordinates">${coordinatesHTML(ledger)}</div></section><section class="fpb-stage"><h3>2 · Build the loop one edge at a time</h3>${button(prefix+'-step',"Next step",!ledger.current.valid)}<output id="${prefix}-step-number">${state.step}/8</output><div id="${prefix}-ledger">${ledgerHTML(state,actual)}</div></section><section class="fpb-stage"><h3>3 · Cancel gauge phases at every endpoint</h3><div id="${prefix}-gauge">${gaugeHTML(state,actual)}</div></section><section class="fpb-stage"><h3>4 · One plaquette flux and the full-BZ sum</h3><div id="${prefix}-total">${totalHTML(actual,ledger)}</div></section><section class="fpb-stage"><h3>Prediction checks</h3>${questions.map((_q,i)=>questionHTML(prefix,state,i)).join('')}</section>`+`<details class="fpb-reference" data-fpb-native="proof"${state.proofOpen?' open':''}><summary>Data provenance, scope, and reproduction</summary><p>The four bounded learning references come from production quantum_geometry_lab calls. The result view uses only the current result.fhsReplay, without substituting a reference case. Raw links are ordered rx(A), ry(B), rx(D), ry(A); the last two are conjugated in the loop. Source hashes use UTF-8 and LF normalization.</p><p data-math-ignore>scripts/check-fhs-plaquette-reference.py --check</p><p>SSH has a one-dimensional Zak chain, not two-dimensional FHS plaquettes. Recompute an old record without fhsReplay to obtain the edge data for that calculation.</p></details>`+(mode==='lesson'&&canCopy?button(prefix+'-copy',"Copy this complete reference input to the original experiment")+"<p>Copying fills the complete supported QWZ input and clears the old form draft. Run manually afterward. Plaquette indices, gauge-link phases, predictions, and notes are not core inputs.</p>":"<p>This card neither calculates automatically nor writes completion records. Run the original experiment manually to update the result.</p>")+`<p id="${prefix}-copy-status" class="fpb-feedback" role="status"></p><label class="fpb-note" for="${prefix}-note">${"Write your own explanation (kept only in this page's memory)"}<textarea id="${prefix}-note" rows="3" maxlength="2000">${esc(state.note)}</textarea></label>${button(prefix+'-reset',"Reset this replay card")}`;}

export function fhsPlaquetteBridgeHTML(lessonId){return FHS_PLAQUETTE_BRIDGE_HOOKS[lessonId]?"<section class=\"fpb-prerequisite\" aria-label=\"Optional four-edge FHS replay\"><details class=\"fpb-bridge\" data-fpb-bridge=\"oriented-plaquette\"><summary>Replay an FHS plaquette from four complex links</summary><div class=\"fpb-body\" data-fpb-body></div></details></section>":'';}
export function fhsPlaquetteResultHTML(result){if(result?.model==='ssh')return "<p class=\"fpb-scope\">This is one-dimensional SSH with a closed Zak chain; a two-dimensional FHS plaquette replay does not apply.</p>";if(!result?.fhsReplay)return "<p class=\"fpb-warning\">This record has no saved FHS edge data. Its existing results remain readable. Recompute QWZ to replay the plaquette from that calculation.</p>";return '<section class="fpb-prerequisite" data-fpb-result><div class="fpb-body" data-fpb-body></div></section>';}

function bindCard({root,lessonId,result,isCurrent=()=>true,stateStore=new Map(),onOpenLab,disclosure,stateKey,mode}){
 const body=root?.querySelector?.('[data-fpb-body]'),detail=disclosure||root?.querySelector?.('[data-fpb-bridge]'),store=stateStore instanceof Map?stateStore:new Map(),key=stateKey||(mode==='lesson'?lessonId+':oriented-plaquette':sourceKey(result)),state=restore(store.get(key)),owner={},bindings=[],prefix=mode==='lesson'?'fpb-geometry-topology':'fpb-result';let alive=true,busy=false,ticket=0;
 if(body)owners.set(body,owner);if(mode==='result'&&detail)state.open=readOpen(detail);
 const $=name=>body?.querySelector('#'+prefix+'-'+name),active=()=>alive&&!!body&&owners.get(body)===owner&&root?.isConnected!==false&&isCurrent()&&root.querySelector('[data-fpb-body]')===body;
 const save=()=>{if(active())store.set(key,clone(state));};
 const capture=()=>{if(!active())return;if(detail)state.open=readOpen(detail);const proof=body.querySelector('[data-fpb-native="proof"]');if(proof)state.proofOpen=readOpen(proof);if($('note'))state.note=String($('note').value).slice(0,2000);for(const[name,allowed]of [['case',references().map(row=>row.id)],['cell',['interior','boundary-xy']],['frame',['before','after']]]){const node=$(name),field=name==='case'?'caseId':name==='cell'?'cellId':'frame';if(node&&allowed.includes(node.value))state[field]=node.value;}for(let i=0;i<4;i++){const value=$('q'+i)?.value;if((value===''||questions[i].options.some(([id])=>id===value))&&value!==state.choices[i]){state.choices[i]=value;state.checked[i]=false;}}save();};
 const attach=(node,event,fn)=>{if(node){node[event]=fn;bindings.push([node,event,fn]);}};
 const bind=(name,event,fn)=>{const node=$(name);attach(node,event,()=>{if(!active()||$(name)!==node||node.disabled)return;capture();fn(node);save();});};
 const paintQuestion=i=>{const q=questions[i],choice=state.choices[i],checked=state.checked[i]&&choice,node=$('feedback'+i);if(node){node.textContent=checked?(choice===q.answer?'✓ ':'')+q.feedback[choice]:'';node.setAttribute('class','fpb-feedback'+(checked&&choice===q.answer?' fpb-correct':''));}if($('check'+i))$('check'+i).disabled=!choice;};
 const paint=()=>{if(!active())return;const actual=getResult(state,result),ledger=fhsPlaquetteLedger(actual,state);if($('parameters'))$('parameters').textContent=parametersText(actual);for(const[name,html]of [['coordinates',coordinatesHTML(ledger)],['ledger',ledgerHTML(state,actual)],['gauge',gaugeHTML(state,actual)],['total',totalHTML(actual,ledger)]])if($(name))$(name).innerHTML=html;if($('step')){$('step').disabled=!ledger.current.valid;$('step').textContent=state.step>=8?"Replay from the raw overlaps":"Next step";}if($('step-number'))$('step-number').textContent=state.step+'/8';for(let i=0;i<4;i++)paintQuestion(i);};
 const clearCopy=()=>{ticket++;state.copyOutcome='';if($('copy-status'))$('copy-status').textContent='';};
 function draw(){if(!active())return;body.innerHTML=bodyHTML(prefix,state,result,mode,typeof onOpenLab==='function');const proof=body.querySelector('[data-fpb-native="proof"]');if(proof){proof.open=state.proofOpen;attach(proof,'ontoggle',()=>{if(active()&&body.querySelector('[data-fpb-native="proof"]')===proof){state.proofOpen=readOpen(proof);save();}});}for(const name of ['case','cell','frame'])bind(name,'onchange',()=>{if(name!=='frame')state.step=0;clearCopy();paint();});bind('step','onclick',()=>{state.step=state.step>=8?0:state.step+1;paint();});for(let i=0;i<4;i++){bind('q'+i,'onchange',()=>paintQuestion(i));bind('check'+i,'onclick',()=>{state.checked[i]=true;paintQuestion(i);});}bind('note','oninput',node=>{state.note=String(node.value).slice(0,2000);});bind('reset','onclick',()=>{const open=state.open;Object.assign(state,initial(),{open});clearCopy();draw();$('cell')?.focus?.({preventScroll:true});});const copy=$('copy');if(copy){copy.disabled=busy;attach(copy,'onclick',async()=>{if(!active()||$('copy')!==copy||copy.disabled||busy)return;capture();const request=fhsPlaquetteLabRequest({caseId:state.caseId}),id=++ticket;busy=true;copy.disabled=true;save();try{const accepted=await onOpenLab(clone(request));if(accepted===false)throw Error('Rejected');if(active()&&$('copy')===copy&&ticket===id){state.copyOutcome='success';$('copy-status').textContent="The complete input was copied. Run it manually in the original experiment.";save();}}catch(_error){if(active()&&$('copy')===copy&&ticket===id){state.copyOutcome='error';$('copy-status').textContent="The input could not be copied. Please try again.";save();}}finally{busy=false;if(active()&&$('copy'))$('copy').disabled=false;}});}paint();save();}
 if(body){if(mode==='lesson'&&detail){detail.open=state.open;attach(detail,'ontoggle',()=>{if(active()){state.open=readOpen(detail);save();}});}draw();}
 const cleanup=()=>{if(!alive)return;capture();alive=false;ticket++;for(const[node,event,fn]of bindings)if(node[event]===fn)node[event]=null;if(body&&owners.get(body)===owner)owners.delete(body);};cleanup.snapshot=()=>{capture();return clone(state);};return cleanup;
}
export function bindFhsPlaquetteBridge(options={}){if(!FHS_PLAQUETTE_BRIDGE_HOOKS[options.lessonId]){const cleanup=()=>{};cleanup.snapshot=()=>({});return cleanup;}return bindCard({...options,mode:'lesson'});}
export function bindFhsPlaquetteResult(options={}){return bindCard({...options,mode:'result'});}
